SET check_function_bodies = off;

ALTER TABLE ONLY public.profiles ADD CONSTRAINT profiles_org_id_fkey FOREIGN KEY (org_id) REFERENCES public.organizations(id);
ALTER TABLE ONLY public.proposal_citation_reports ADD CONSTRAINT proposal_citation_reports_proposal_id_fkey FOREIGN KEY (proposal_id) REFERENCES public.proposals(id) ON DELETE CASCADE;
ALTER TABLE ONLY public.proposal_citations ADD CONSTRAINT proposal_citations_chunk_id_fkey FOREIGN KEY (chunk_id) REFERENCES public.knowledge_chunks(id) ON DELETE RESTRICT;
ALTER TABLE ONLY public.proposal_citations ADD CONSTRAINT proposal_citations_section_id_fkey FOREIGN KEY (section_id) REFERENCES public.proposal_sections(id) ON DELETE CASCADE;
ALTER TABLE ONLY public.proposal_reviews ADD CONSTRAINT proposal_reviews_proposal_id_fkey FOREIGN KEY (proposal_id) REFERENCES public.proposals(id) ON DELETE CASCADE;
DO $do$ BEGIN EXECUTE 'ALTER TABLE ONLY public.proposals ADD CONSTRAINT proposals_org_id_fkey FOREIGN KEY (org_id) REFERENCES public.organizations(id) NOT VALID'; EXCEPTION WHEN others THEN RAISE NOTICE 'skipped: %', SQLERRM; END $do$;
DO $do$ BEGIN EXECUTE 'ALTER TABLE ONLY public.proposals ADD CONSTRAINT proposals_template_id_fkey FOREIGN KEY (template_id) REFERENCES public.proposal_templates(id) ON DELETE SET NULL NOT VALID'; EXCEPTION WHEN others THEN RAISE NOTICE 'skipped: %', SQLERRM; END $do$;
ALTER TABLE ONLY public.shared_fit_reports ADD CONSTRAINT shared_fit_reports_grant_id_fkey FOREIGN KEY (grant_id) REFERENCES public.grants(id) ON DELETE CASCADE;
DO $do$ BEGIN EXECUTE 'ALTER TABLE ONLY public.submissions ADD CONSTRAINT submissions_grant_id_fkey FOREIGN KEY (grant_id) REFERENCES public.grants(id) ON DELETE CASCADE NOT VALID'; EXCEPTION WHEN others THEN RAISE NOTICE 'skipped: %', SQLERRM; END $do$;
DO $do$ BEGIN EXECUTE 'ALTER TABLE ONLY public.submissions ADD CONSTRAINT submissions_org_id_fkey FOREIGN KEY (org_id) REFERENCES public.organizations(id) NOT VALID'; EXCEPTION WHEN others THEN RAISE NOTICE 'skipped: %', SQLERRM; END $do$;
ALTER TABLE ONLY public.user_organizations ADD CONSTRAINT user_organizations_org_id_fkey FOREIGN KEY (org_id) REFERENCES public.organizations(id) ON DELETE CASCADE;

-- Grants for new tables (only where authenticated has none yet)
DO $g$ DECLARE r record; BEGIN
FOR r IN SELECT c.relname FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
  WHERE n.nspname='public' AND c.relkind IN ('r','v')
  AND NOT EXISTS (SELECT 1 FROM information_schema.role_table_grants g WHERE g.grantee='authenticated' AND g.table_schema='public' AND g.table_name=c.relname)
LOOP
  EXECUTE format('GRANT SELECT, INSERT, UPDATE, DELETE ON public.%I TO authenticated', r.relname);
  EXECUTE format('GRANT ALL ON public.%I TO service_role', r.relname);
END LOOP;
END $g$;
GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA public TO authenticated, service_role;
GRANT SELECT ON public.grants, public.funders TO anon;

CREATE POLICY "Admins manage discovery sources registry" ON public.discovery_sources_registry TO authenticated USING (public.has_role(auth.uid(), 'admin'::public.app_role)) WITH CHECK (public.has_role(auth.uid(), 'admin'::public.app_role));
