CREATE POLICY "Authenticated users can read competitive grants" ON public.competitive_grants FOR SELECT TO authenticated USING (true);
DROP POLICY IF EXISTS "Org members can view org funders" ON public.funders;
CREATE POLICY "Org members can view org funders" ON public.funders FOR SELECT USING (((org_id IS NULL) OR (org_id IN (SELECT user_organizations.org_id FROM public.user_organizations WHERE (user_organizations.user_id = auth.uid())))));
DROP POLICY IF EXISTS "Org members can view org grants" ON public.grants;
CREATE POLICY "Org members can view org grants" ON public.grants FOR SELECT USING (((org_id IS NULL) OR (org_id IN (SELECT user_organizations.org_id FROM public.user_organizations WHERE (user_organizations.user_id = auth.uid())))));
DROP POLICY IF EXISTS "Org members can view org proposals" ON public.proposals;
CREATE POLICY "Org members can view org proposals" ON public.proposals FOR SELECT TO authenticated USING (((org_id IS NOT NULL) AND (org_id IN (SELECT user_organizations.org_id FROM public.user_organizations WHERE (user_organizations.user_id = auth.uid())))));
DROP POLICY IF EXISTS "Org members can view org submissions" ON public.submissions;
CREATE POLICY "Org members can view org submissions" ON public.submissions FOR SELECT TO authenticated USING (((org_id IS NOT NULL) AND (org_id IN (SELECT user_organizations.org_id FROM public.user_organizations WHERE (user_organizations.user_id = auth.uid())))));

CREATE OR REPLACE FUNCTION public.user_org_ids(_uid uuid, _roles text[] DEFAULT NULL) RETURNS SETOF uuid
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public' AS $$
  SELECT org_id FROM public.user_organizations WHERE user_id = _uid AND (_roles IS NULL OR role = ANY(_roles));
$$;

CREATE POLICY "Org owners and admins can add members" ON public.user_organizations FOR INSERT TO authenticated WITH CHECK (org_id IN (SELECT public.user_org_ids(auth.uid(), ARRAY['owner','admin'])));
CREATE POLICY "Org owners and admins can update members" ON public.user_organizations FOR UPDATE TO authenticated USING (org_id IN (SELECT public.user_org_ids(auth.uid(), ARRAY['owner','admin'])));
CREATE POLICY "Org owners can remove members" ON public.user_organizations FOR DELETE TO authenticated USING ((org_id IN (SELECT public.user_org_ids(auth.uid(), ARRAY['owner']))) AND (user_id <> auth.uid()));
CREATE POLICY "Users can view org members of their orgs" ON public.user_organizations FOR SELECT TO authenticated USING (org_id IN (SELECT public.user_org_ids(auth.uid())));
CREATE POLICY "Users can view their own org memberships" ON public.user_organizations FOR SELECT TO authenticated USING ((user_id = auth.uid()));
CREATE POLICY "Users can view organizations they belong to" ON public.organizations FOR SELECT TO authenticated USING (id IN (SELECT public.user_org_ids(auth.uid())));

